'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `bind` method', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'bind' ), true, 'has property' );
	t.strictEqual( isFunction( f.bind ), true, 'has method' );
	t.end();
});

tape( 'the method returns a new function', function test( t ) {
	var f;
	var g;

	f = new Fcn( 'x', 'y', 'return x + y' );
	g = f.bind( null );
	t.strictEqual( isFunction( g ), true, 'returns a function' );
	t.notEqual( g, f, 'returns a new function' );
	t.end();
});

tape( 'the method creates a function with a bound `this` value', function test( t ) {
	var ctx;
	var f;
	var g;
	var v;

	ctx = {
		'z': 10
	};
	f = new Fcn( 'x', 'y', 'return this.z + x + y' );
	g = f.bind( ctx );
	v = g( 1, 2 );
	t.strictEqual( v, 13, 'returns expected value' );
	t.end();
});

tape( 'the method supports pre-filling arguments', function test( t ) {
	var f;
	var g;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	g = f.bind( null, 1 );
	v = g( 2 );
	t.strictEqual( v, 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports pre-filling all arguments', function test( t ) {
	var f;
	var g;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	g = f.bind( null, 3, 4 );
	v = g();
	t.strictEqual( v, 7, 'returns expected value' );
	t.end();
});

tape( 'the bound function\'s `length` is reduced by the number of pre-filled arguments', function test( t ) {
	var f;
	var g;

	f = new Fcn( 'x', 'y', 'z', 'return x + y + z' );
	g = f.bind( null, 1 );
	t.strictEqual( g.length, 2, 'returns expected value' );
	t.end();
});

tape( 'the bound function does not have a `prototype` property', function test( t ) {
	var f;
	var g;

	f = new Fcn( 'x', 'y', 'return x + y' );
	g = f.bind( null );
	t.strictEqual( g.prototype, undefined, 'returns expected value' );
	t.end();
});
